//! Embedded datasets, parsed once.
//!
//! The files under `data/` are generated by the scripts in `tools/` and compiled into
//! the binary with `include_str!`, so the engine needs no I/O and native and wasm see
//! exactly the same numbers.
//!
//! Wiring status:
//!
//! | File | State |
//! |---|---|
//! | `data/history/monthly.csv` | typed: [`History`] |
//! | `data/actuarial/ssa-life-table.csv` | typed: [`LifeTable`] |
//! | `data/actuarial/ssa-mortality-improvement.csv` | typed: [`MortalityImprovement`] |
//! | `data/tax/us-federal-2026.json` | embedded and parsed to JSON; typed view is `tax::TaxLaw::from_data` (TODO, tax owner) |
//! | `data/tax/us-states-2026.json` | embedded and parsed to JSON; same |
//! | `data/actuarial/params.json` | embedded and parsed to JSON; each owner (career, health, housing, ...) adds a typed section here |
//! | `data/history/calibration.json` | not embedded: it is a test fixture for economy calibration tests |
//! | `data/col/cities.csv` | not embedded (334 KB): the web UI resolves a city pair to cost-of-living factors and writes them into the `relocate` event |
//!
//! Contract: [`Data::embedded`] never fails at run time. A malformed embedded file is a
//! build defect and is caught by this module's tests, so parsing panics with the file
//! name rather than returning errors every caller would have to thread through.
//!
//! Tests and what-if tools can build a [`Data`] by hand (all fields are public) and
//! pass it wherever `&Data` is accepted.

use std::sync::OnceLock;

use serde_json::Value;

use crate::model::{Sex, YearMonth};

const MONTHLY_CSV: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../data/history/monthly.csv"
));
const LIFE_TABLE_CSV: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../data/actuarial/ssa-life-table.csv"
));
const IMPROVEMENT_CSV: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../data/actuarial/ssa-mortality-improvement.csv"
));
const TAX_FEDERAL_JSON: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../data/tax/us-federal-2026.json"
));
const TAX_STATES_JSON: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../data/tax/us-states-2026.json"
));
const ACTUARIAL_JSON: &str = include_str!(concat!(
    env!("CARGO_MANIFEST_DIR"),
    "/../../data/actuarial/params.json"
));

/// A dataset could not be parsed.
#[derive(Clone, Debug, PartialEq, Eq, thiserror::Error)]
#[error("{file}: {message}")]
pub struct DataError {
    /// Which dataset.
    pub file: &'static str,
    /// What is wrong, with a line number where applicable.
    pub message: String,
}

/// Every dataset the engine uses.
#[derive(Clone, Debug)]
pub struct Data {
    /// Monthly market and macro history.
    pub history: History,
    /// SSA period life table.
    pub life_table: LifeTable,
    /// SSA projected annual mortality improvement by sex and age band.
    pub mortality_improvement: Vec<MortalityImprovement>,
    /// `data/tax/us-federal-2026.json` as parsed JSON. Read through
    /// `tax::TaxLaw::from_data`, not directly.
    pub tax_federal: Value,
    /// `data/tax/us-states-2026.json` as parsed JSON, keyed by two-letter state code.
    pub tax_states: Value,
    /// `data/actuarial/params.json` as parsed JSON: sections `mortality`, `earnings`,
    /// `unemployment`, `healthcare`, `long_term_care`, `expense_shocks`, `children`,
    /// `retirement_spending`, `housing`, `equity_compensation`, `crypto`,
    /// `withdrawal_rules`.
    pub actuarial: Value,
}

impl Data {
    /// The datasets compiled into this build. Parsed on first use, then shared.
    pub fn embedded() -> &'static Data {
        static DATA: OnceLock<Data> = OnceLock::new();
        DATA.get_or_init(|| Data::parse_embedded().unwrap_or_else(|e| panic!("embedded data: {e}")))
    }

    fn parse_embedded() -> Result<Data, DataError> {
        let json = |file: &'static str, text: &str| {
            serde_json::from_str::<Value>(text).map_err(|e| DataError {
                file,
                message: e.to_string(),
            })
        };
        Ok(Data {
            history: History::parse_csv(MONTHLY_CSV)?,
            life_table: LifeTable::parse_csv(LIFE_TABLE_CSV)?,
            mortality_improvement: MortalityImprovement::parse_csv(IMPROVEMENT_CSV)?,
            tax_federal: json("data/tax/us-federal-2026.json", TAX_FEDERAL_JSON)?,
            tax_states: json("data/tax/us-states-2026.json", TAX_STATES_JSON)?,
            actuarial: json("data/actuarial/params.json", ACTUARIAL_JSON)?,
        })
    }
}

/// Monthly history from 1926. All return and rate series have one entry per month
/// starting at [`History::start`]; a month with no observation is `f64::NAN` (some
/// series start later, and the latest month of slow series may be missing).
///
/// Units: `equity_us`, `equity_intl`, `bond10`, `gold`, `home` and `tbill` are nominal
/// total returns for the month as decimals; `cpi` is the month's inflation as a
/// decimal; `long_yield`, `mortgage30` and `unemployment` are annualised levels as
/// decimals.
#[derive(Clone, Debug, Default)]
pub struct History {
    /// First month of the record.
    pub start: YearMonth,
    /// US total stock market return.
    pub equity_us: Vec<f64>,
    /// One-month Treasury bill return.
    pub tbill: Vec<f64>,
    /// 10-year Treasury total return.
    pub bond10: Vec<f64>,
    /// CPI-U inflation for the month.
    pub cpi: Vec<f64>,
    /// National home price index change.
    pub home: Vec<f64>,
    /// Long government bond yield (annualised level).
    pub long_yield: Vec<f64>,
    /// 30-year fixed mortgage rate (annualised level).
    pub mortgage30: Vec<f64>,
    /// Unemployment rate (level).
    pub unemployment: Vec<f64>,
    /// 1 in NBER recession months.
    pub recession: Vec<u8>,
    /// Developed ex-US stock return (starts 1975).
    pub equity_intl: Vec<f64>,
    /// Gold return (starts 1968).
    pub gold: Vec<f64>,
}

impl History {
    /// Number of months in the record.
    pub fn len(&self) -> usize {
        self.equity_us.len()
    }

    /// True if the record is empty.
    pub fn is_empty(&self) -> bool {
        self.equity_us.is_empty()
    }

    /// The calendar month of row `i`.
    pub fn month(&self, i: usize) -> YearMonth {
        self.start + i as i32
    }

    /// Row index of a calendar month, if it is inside the record.
    pub fn index_of(&self, ym: YearMonth) -> Option<usize> {
        usize::try_from(ym - self.start)
            .ok()
            .filter(|&i| i < self.len())
    }

    /// Index of the first row at which every series in `series` has a value from then
    /// on without gaps up to its last observation. Bootstraps that need a set of
    /// series jointly start here.
    pub fn first_complete_row(series: &[&[f64]]) -> usize {
        series
            .iter()
            .map(|s| s.iter().position(|v| !v.is_nan()).unwrap_or(s.len()))
            .max()
            .unwrap_or(0)
    }

    /// Parses `data/history/monthly.csv`. Columns are located by header name, extra
    /// columns (quality flags) are ignored, and empty cells become NaN.
    pub fn parse_csv(text: &str) -> Result<History, DataError> {
        const FILE: &str = "data/history/monthly.csv";
        let err = |message: String| DataError {
            file: FILE,
            message,
        };
        let mut lines = text.lines().filter(|l| !l.trim().is_empty());
        let header: Vec<&str> = lines
            .next()
            .ok_or_else(|| err("empty file".into()))?
            .split(',')
            .collect();
        let col = |name: &str| {
            header
                .iter()
                .position(|h| h.trim() == name)
                .ok_or_else(|| err(format!("missing column {name:?}")))
        };
        let c_date = col("date")?;
        let names = [
            "equity_us",
            "tbill",
            "bond10",
            "cpi",
            "home",
            "long_yield",
            "mortgage30",
            "unemployment",
            "recession",
            "equity_intl",
            "gold",
        ];
        let mut idx = [0usize; 11];
        for (slot, name) in idx.iter_mut().zip(names) {
            *slot = col(name)?;
        }
        let mut cols: [Vec<f64>; 11] = Default::default();
        let mut start = None;
        for (row, line) in lines.enumerate() {
            let cells: Vec<&str> = line.split(',').collect();
            let line_no = row + 2;
            let date: YearMonth = cells
                .get(c_date)
                .ok_or_else(|| err(format!("line {line_no}: no date")))?
                .parse()
                .map_err(|e| err(format!("line {line_no}: {e}")))?;
            let first = *start.get_or_insert(date);
            if date - first != row as i32 {
                return Err(err(format!(
                    "line {line_no}: {date} is not contiguous with the previous month"
                )));
            }
            for (values, &c) in cols.iter_mut().zip(&idx) {
                let cell = cells.get(c).map_or("", |s| s.trim());
                let v = if cell.is_empty() {
                    f64::NAN
                } else {
                    cell.parse::<f64>()
                        .map_err(|_| err(format!("line {line_no}: bad number {cell:?}")))?
                };
                values.push(v);
            }
        }
        let [equity_us, tbill, bond10, cpi, home, long_yield, mortgage30, unemployment, recession, equity_intl, gold] =
            cols;
        Ok(History {
            start: start.ok_or_else(|| err("no data rows".into()))?,
            equity_us,
            tbill,
            bond10,
            cpi,
            home,
            long_yield,
            mortgage30,
            unemployment,
            recession: recession.iter().map(|v| u8::from(*v > 0.5)).collect(),
            equity_intl,
            gold,
        })
    }
}

/// A period life table: probability of dying within a year at each age. Row `i` is
/// age `i`.
#[derive(Clone, Debug, Default)]
pub struct LifeTable {
    /// Male one-year death probability by age.
    pub male_qx: Vec<f64>,
    /// Female one-year death probability by age.
    pub female_qx: Vec<f64>,
}

impl LifeTable {
    /// Highest age in the table.
    pub fn max_age(&self) -> usize {
        self.male_qx.len().saturating_sub(1)
    }

    /// One-year death probability at an integer age. Ages beyond the table use its
    /// last row; `Unspecified` is the average of the two sexes.
    pub fn qx(&self, sex: Sex, age: usize) -> f64 {
        let i = age.min(self.max_age());
        match sex {
            Sex::Male => self.male_qx[i],
            Sex::Female => self.female_qx[i],
            Sex::Unspecified => 0.5 * (self.male_qx[i] + self.female_qx[i]),
        }
    }

    /// Parses `data/actuarial/ssa-life-table.csv` (columns `age`, `male_qx`,
    /// `female_qx`, others ignored).
    pub fn parse_csv(text: &str) -> Result<LifeTable, DataError> {
        const FILE: &str = "data/actuarial/ssa-life-table.csv";
        let err = |message: String| DataError {
            file: FILE,
            message,
        };
        let mut lines = text.lines().filter(|l| !l.trim().is_empty());
        let header: Vec<&str> = lines
            .next()
            .ok_or_else(|| err("empty file".into()))?
            .split(',')
            .collect();
        let col = |name: &str| {
            header
                .iter()
                .position(|h| h.trim() == name)
                .ok_or_else(|| err(format!("missing column {name:?}")))
        };
        let (c_age, c_m, c_f) = (col("age")?, col("male_qx")?, col("female_qx")?);
        let mut table = LifeTable::default();
        for (row, line) in lines.enumerate() {
            let cells: Vec<&str> = line.split(',').collect();
            let num = |c: usize| {
                cells
                    .get(c)
                    .and_then(|s| s.trim().parse::<f64>().ok())
                    .ok_or_else(|| err(format!("line {}: bad number", row + 2)))
            };
            if num(c_age)? != row as f64 {
                return Err(err(format!("line {}: ages must run 0, 1, 2, ...", row + 2)));
            }
            table.male_qx.push(num(c_m)?);
            table.female_qx.push(num(c_f)?);
        }
        if table.male_qx.len() < 100 {
            return Err(err("expected at least ages 0 to 99".into()));
        }
        Ok(table)
    }
}

/// Projected annual rate of mortality improvement for one sex and age band.
#[derive(Clone, Debug, PartialEq)]
pub struct MortalityImprovement {
    /// Sex the band applies to; the file's "unisex" rows are `Unspecified`.
    pub sex: Sex,
    /// Lowest age in the band.
    pub age_from: u32,
    /// Highest age in the band, inclusive (`u32::MAX` for an open band such as "85+").
    pub age_to: u32,
    /// Annual reduction in death rates up to 2050, as a decimal (0.0085 = 0.85%).
    pub reduction_to_2050: f64,
    /// Annual reduction in death rates from 2050 on, as a decimal.
    pub reduction_after_2050: f64,
}

impl MortalityImprovement {
    /// Parses `data/actuarial/ssa-mortality-improvement.csv`. The file gives percent
    /// per year; values are converted to decimals.
    pub fn parse_csv(text: &str) -> Result<Vec<MortalityImprovement>, DataError> {
        const FILE: &str = "data/actuarial/ssa-mortality-improvement.csv";
        let err = |message: String| DataError {
            file: FILE,
            message,
        };
        let mut out = Vec::new();
        for (row, line) in text
            .lines()
            .filter(|l| !l.trim().is_empty())
            .enumerate()
            .skip(1)
        {
            let bad = || err(format!("line {}: expected sex,age_band,pct,pct", row + 1));
            let cells: Vec<&str> = line.split(',').map(str::trim).collect();
            if cells.len() < 4 {
                return Err(bad());
            }
            let sex = match cells[0] {
                "male" => Sex::Male,
                "female" => Sex::Female,
                "unisex" => Sex::Unspecified,
                _ => return Err(bad()),
            };
            let (age_from, age_to) = match cells[1].split_once('-') {
                Some((a, b)) => (a.parse().map_err(|_| bad())?, b.parse().map_err(|_| bad())?),
                None => {
                    let a = cells[1].trim_end_matches('+').parse().map_err(|_| bad())?;
                    (a, u32::MAX)
                }
            };
            let pct = |s: &str| s.parse::<f64>().map(|v| v / 100.0).map_err(|_| bad());
            out.push(MortalityImprovement {
                sex,
                age_from,
                age_to,
                reduction_to_2050: pct(cells[2])?,
                reduction_after_2050: pct(cells[3])?,
            });
        }
        if out.is_empty() {
            return Err(err("no rows".into()));
        }
        Ok(out)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_data_parses() {
        let d = Data::embedded();
        assert_eq!(d.history.start, YearMonth::ym(1926, 7));
        assert!(d.history.len() >= 1200);
        for s in [
            &d.history.tbill,
            &d.history.cpi,
            &d.history.bond10,
            &d.history.gold,
        ] {
            assert_eq!(s.len(), d.history.len());
        }
        assert_eq!(d.history.recession.len(), d.history.len());
        assert!(d.history.equity_us.iter().all(|v| v.is_finite()));
        assert_eq!(d.history.index_of(YearMonth::ym(1926, 8)), Some(1));
        assert_eq!(d.history.index_of(YearMonth::ym(1900, 1)), None);
        // International stocks start in 1975, so a joint bootstrap starts there.
        let first = History::first_complete_row(&[&d.history.equity_us, &d.history.equity_intl]);
        assert_eq!(d.history.month(first), YearMonth::ym(1975, 1));
        // The 1929-33 contraction is flagged.
        assert_eq!(
            d.history.recession[d.history.index_of(YearMonth::ym(1931, 6)).unwrap()],
            1
        );
    }

    #[test]
    fn life_table_is_sane() {
        let t = &Data::embedded().life_table;
        assert!(t.max_age() >= 99);
        assert!(t.qx(Sex::Male, 40) > t.qx(Sex::Female, 40));
        assert!(t.qx(Sex::Unspecified, 90) > t.qx(Sex::Unspecified, 60));
        assert!(t.qx(Sex::Male, 500) <= 1.0);
        let imp = &Data::embedded().mortality_improvement;
        assert!(imp.iter().any(|b| b.sex == Sex::Female));
        assert!(imp
            .iter()
            .all(|b| (0.0..0.05).contains(&b.reduction_to_2050)));
    }

    #[test]
    fn json_datasets_have_the_expected_sections() {
        let d = Data::embedded();
        assert!(d.tax_federal["income_tax"]["ordinary_brackets"].is_object());
        assert!(d.tax_states["CO"]["brackets"].is_object());
        assert!(d.actuarial["mortality"].is_object());
    }

    #[test]
    fn csv_errors_name_the_line() {
        let e = History::parse_csv("date,equity_us\n1926-07,0.1\n").unwrap_err();
        assert!(e.to_string().contains("missing column"), "{e}");
        let e = LifeTable::parse_csv("age,male_qx,female_qx\n0,0.1,0.1\n2,0.1,0.1\n").unwrap_err();
        assert!(e.to_string().contains("line 3"), "{e}");
    }
}
